    notAccepted: "ผู้ใช้นี้ยังไม่ได้ยอมรับนโยบาย",
    noSignature: "ยังไม่มีลายเซ็น — จะแสดงเมื่อผู้ใช้อัปโหลดลายเซ็นในโปรไฟล์",
